// Package store owns the Postgres schema (embedded goose migrations) and the
// connection pool. Queries are generated by sqlc into package db.
package store

import (
	"context"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"

	"github.com/dottio123/ferricade/internal/store/db"
)

//go:embed migrations/*.sql
var migrations embed.FS

// Open connects a pool to url and checks that the database answers.
// timestamptz values are scanned as UTC.
func Open(ctx context.Context, url string) (*pgxpool.Pool, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, fmt.Errorf("parse database url: %w", err)
	}
	return openConfig(ctx, cfg)
}

func openConfig(ctx context.Context, cfg *pgxpool.Config) (*pgxpool.Pool, error) {
	cfg.AfterConnect = func(_ context.Context, conn *pgx.Conn) error {
		conn.TypeMap().RegisterType(&pgtype.Type{
			Name:  "timestamptz",
			OID:   pgtype.TimestamptzOID,
			Codec: &pgtype.TimestamptzCodec{ScanLocation: time.UTC},
		})
		return nil
	}
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("open database: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("ping database: %w", err)
	}
	return pool, nil
}

// Migrate applies every pending embedded migration.
func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	_, _, err := MigrateVersion(ctx, pool)
	return err
}

// MigrateVersion applies every pending embedded migration and returns the
// schema version before and after running them.
func MigrateVersion(ctx context.Context, pool *pgxpool.Pool) (before, after int64, err error) {
	sqlDB := stdlib.OpenDBFromPool(pool)
	defer sqlDB.Close()

	fsys, err := fs.Sub(migrations, "migrations")
	if err != nil {
		return 0, 0, fmt.Errorf("migrations: %w", err)
	}
	provider, err := goose.NewProvider(goose.DialectPostgres, sqlDB, fsys)
	if err != nil {
		return 0, 0, fmt.Errorf("migrations: %w", err)
	}
	before, err = provider.GetDBVersion(ctx)
	if err != nil {
		return 0, 0, fmt.Errorf("migrations version: %w", err)
	}
	if _, err := provider.Up(ctx); err != nil {
		return before, before, fmt.Errorf("migrate: %w", err)
	}
	after, err = provider.GetDBVersion(ctx)
	if err != nil {
		return before, before, fmt.Errorf("migrations version: %w", err)
	}
	return before, after, nil
}

// Tx runs fn in a read-committed transaction. It commits when fn returns nil
// and rolls back otherwise, returning fn's error. If fn panics, the
// transaction is rolled back and the panic continues.
func Tx(ctx context.Context, pool *pgxpool.Pool, fn func(q *db.Queries) error) error {
	tx, err := pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.ReadCommitted})
	if err != nil {
		return fmt.Errorf("begin: %w", err)
	}
	// Releases the connection when fn panics. After a commit or an explicit
	// rollback it is a no-op (pgx.ErrTxClosed). It ignores ctx cancellation so
	// a cancelled request still returns its connection cleanly.
	defer func() { _ = tx.Rollback(context.WithoutCancel(ctx)) }()
	if err := fn(db.New(tx)); err != nil {
		if rbErr := tx.Rollback(ctx); rbErr != nil && !errors.Is(rbErr, pgx.ErrTxClosed) {
			return errors.Join(err, fmt.Errorf("rollback: %w", rbErr))
		}
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}
